//! Control flow: zml.ops.while, zml.ops.if and zml.ops.if2, with randomly generated
//! regions.
//!
//! A region is a contiguous range of nodes [start, end) carrying `scope = start + 1`. Its
//! first nodes are `param` nodes bound to the loop state, the captured tensors and, for
//! loops, the iteration counter. Region nodes only read nodes of their own region, so a
//! region is a small program of its own, generated by the same families as the top level.

const std = @import("std");

const zml = @import("zml");

const k = @import("../kit.zig");
const Shape = k.Shape;
const Tensor = k.Tensor;
const Value = k.Value;
const Gen = k.Gen;
const Eval = k.Eval;
const Node = k.Node;
const Writer = k.Writer;
const List = k.List;
const ir = k.ir;
const lower_mod = @import("../lower.zig");

pub const max_depth = 2;

/// Evaluates the nodes of region `scope` in [start, end) with its params bound.
/// Returns the values indexed by `node - start`.
fn evalRegion(e: *Eval, start: u32, end: u32, scope: u32, bindings: []const Value) Eval.Error![]Value {
    const prog = e.prog.?;
    const local = try e.allocator.alloc(Value, end - start);
    var sub: Eval = .{ .allocator = e.allocator, .strict = e.strict, .prog = prog, .bindings = bindings };
    for (start..end) |i| {
        const n = &prog.nodes.items[i];
        if (n.scope != scope) continue;
        var ins: [ir.max_operands]Value = undefined;
        for (n.inputs.slice(), 0..) |in, j| ins[j] = local[in - start];
        local[i - start] = try k.ops.eval(&sub, n, ins[0..n.inputs.len]);
    }
    return local;
}

/// Generates up to `n` nodes in the current region.
fn genBody(g: *Gen, n: usize) k.GenError!void {
    var made: usize = 0;
    var attempts: usize = 0;
    while (made < n and attempts < 30 * n) : (attempts += 1) {
        const fam = g.pickFamily();
        const prop = k.ops.propose(fam, g) catch |err| switch (err) {
            error.Reject => continue,
            error.OutOfMemory => return error.OutOfMemory,
        } orelse {
            made += 1;
            continue;
        };
        _ = g.commit(prop) catch |err| switch (err) {
            error.Reject => continue,
            error.OutOfMemory => return error.OutOfMemory,
        };
        made += 1;
    }
}

/// Opens a region: commits one `param` node per binding.
fn openRegion(g: *Gen, bindings: []const Value) k.GenError!u32 {
    const scope: u32 = @intCast(g.prog.nodes.items.len + 1);
    const saved = .{ g.scope, g.bindings };
    g.scope = scope;
    g.bindings = bindings;
    errdefer {
        g.scope = saved[0];
        g.bindings = saved[1];
    }
    for (bindings, 0..) |b, j| _ = try g.commit(.{ .op = .{ .param = .{ .index = @intCast(j) } }, .shape = b.shape });
    return scope;
}

/// The most recent region node with exactly this shape, tags included.
fn regionResult(g: *Gen, start: usize, scope: u32, sh: Shape) ?u32 {
    var best: ?u32 = null;
    for (start..g.prog.nodes.items.len) |i| {
        const n = g.prog.nodes.items[i];
        if (n.scope != scope or !n.shape.eqlWithTags(sh) or g.values.items[i].allow_inf) continue;
        // Prefer computed nodes over params, but keep params as a fallback.
        if (best == null or n.op != .param or g.chance(0.2)) best = @intCast(i);
    }
    return best;
}

// -----------------------------------------------------------------------------

pub const param = struct {
    pub const Attrs = struct { index: u8 };
    pub const weight = 0;

    pub fn eval(e: *Eval, a: Attrs, node: *const Node, _: []const Value) Eval.Error!Value {
        var v = try e.bindings[a.index].dupe(e.allocator);
        v.shape = node.shape;
        return v;
    }

    pub fn lowerCtl(_: *lower_mod.Ctx, _: []Tensor, idx: u32, _: []const Tensor) Tensor {
        const n = lower_mod.current_ctx.?.prog.nodes.items[idx];
        return lower_mod.binding(n.op.param.index);
    }

    pub fn lower(_: Attrs, _: *const Node, _: []const Tensor) Tensor {
        unreachable;
    }

    pub fn emit(_: Attrs, _: *const Node, _: *Writer, _: []const []const u8) Writer.Error!void {
        unreachable;
    }
};

// -----------------------------------------------------------------------------

pub const while_loop = struct {
    pub const Attrs = struct {
        start: u32,
        end: u32,
        n_state: u8,
        n_caps: u8,
        trip: u8,
        /// Region nodes giving the next value of each state.
        results: List(u32, 4),
        pick: u8,
    };
    pub const weight = 3;

    pub fn propose(g: *Gen) k.GenError!?k.Proposal {
        if (g.depth >= max_depth) return error.Reject;
        const n_state = g.intIn(u8, 1, 2);
        const n_caps = g.intIn(u8, 0, 2);
        var ids: [4]u32 = undefined;
        for (0..n_state + n_caps) |i| ids[i] = try g.operand(.{ .max_rank = 3 });
        for (0..n_state) |i| for (0..i) |j| try g.avoid(.while_aliased_state, ids[i] == ids[j]);
        const start: u32 = @intCast(g.prog.nodes.items.len);
        errdefer g.rollback(start);
        var bindings: [5]Value = undefined;
        for (0..n_state + n_caps) |i| bindings[i] = g.valueOf(ids[i]);
        // The iteration counter, an i32 scalar.
        bindings[n_state + n_caps] = try Value.alloc(g.allocator, .init(.{}, .i32));
        const n_b = n_state + n_caps + 1;
        const saved = .{ g.scope, g.bindings, g.depth };
        const scope = try openRegion(g, bindings[0..n_b]);
        g.depth += 1;
        defer {
            g.scope = saved[0];
            g.bindings = saved[1];
            g.depth = saved[2];
        }
        try genBody(g, g.intIn(usize, 1, 6));
        var a: Attrs = .{ .start = start, .end = 0, .n_state = n_state, .n_caps = n_caps, .trip = g.intIn(u8, 0, 4), .results = .{}, .pick = g.intIn(u8, 0, n_state - 1) };
        for (0..n_state) |j| a.results.append(regionResult(g, start, scope, bindings[j].shape) orelse return error.Reject);
        a.end = @intCast(g.prog.nodes.items.len);
        g.scope = saved[0];
        g.bindings = saved[1];
        _ = try g.commit(.{ .op = .{ .while_loop = a }, .inputs = try k.dupeIds(g, ids[0 .. n_state + n_caps]), .shape = g.shapeOf(ids[a.pick]) });
        return null;
    }

    pub fn eval(e: *Eval, a: Attrs, node: *const Node, ins: []const Value) Eval.Error!Value {
        var bindings = try e.allocator.alloc(Value, a.n_state + a.n_caps + 1);
        for (0..a.n_state + a.n_caps) |i| bindings[i] = ins[i];
        var counter = try e.alloc(.init(.{}, .i32));
        bindings[a.n_state + a.n_caps] = counter;
        const scope = a.start + 1;
        for (0..a.trip) |it| {
            counter.setI(0, @intCast(it));
            const local = try evalRegion(e, a.start, a.end, scope, bindings);
            for (a.results.slice(), 0..) |r, j| bindings[j] = local[r - a.start];
            counter = try e.alloc(.init(.{}, .i32));
            bindings[a.n_state + a.n_caps] = counter;
        }
        var v = try bindings[a.pick].dupe(e.allocator);
        v.shape = node.shape;
        return v;
    }

    pub fn lowerCtl(ctx: *lower_mod.Ctx, tensors: []Tensor, idx: u32, ins: []const Tensor) Tensor {
        _ = tensors;
        const a = ctx.prog.nodes.items[idx].op.while_loop;
        inline for (1..3) |S| inline for (0..3) |C| {
            if (a.n_state == S and a.n_caps == C) return lowerSized(S, C, idx, a, ins);
        };
        unreachable;
    }

    fn lowerSized(comptime S: usize, comptime C: usize, idx: u32, a: Attrs, ins: []const Tensor) Tensor {
        const W = struct {
            caps: [C]Tensor,
            trip: i64,
            node: u32,
            pub const State = struct { i: Tensor, s: [S]Tensor };

            pub fn cond(w: @This(), st: State) Tensor {
                return st.i.cmp(.LT, Tensor.scalar(w.trip, .i32));
            }

            pub fn body(w: @This(), st: State) State {
                const ctx = lower_mod.current_ctx.?;
                const at = ctx.prog.nodes.items[w.node].op.while_loop;
                var b: [S + C + 1]Tensor = undefined;
                for (0..S) |j| b[j] = st.s[j];
                for (0..C) |j| b[S + j] = w.caps[j];
                b[S + C] = st.i;
                lower_mod.lowerRegion(ctx, at.start, at.end, at.start + 1, &b);
                var next: [S]Tensor = undefined;
                for (0..S) |j| next[j] = ctx.tensors[at.results.slice()[j]];
                return .{ .i = st.i.addConstant(1), .s = next };
            }
        };
        var caps: [C]Tensor = undefined;
        for (0..C) |j| caps[j] = ins[S + j];
        var s: [S]Tensor = undefined;
        for (0..S) |j| s[j] = ins[j];
        const res = zml.ops.@"while"(W, .{ .caps = caps, .trip = a.trip, .node = idx }, .{ .i = Tensor.scalar(0, .i32), .s = s });
        return res.s[a.pick];
    }

    pub fn lower(_: Attrs, _: *const Node, _: []const Tensor) Tensor {
        unreachable;
    }

    pub fn emitCtl(prog: *const ir.Program, idx: u32, w: *Writer, names: []const []const u8, indent: usize) Writer.Error!void {
        const n = prog.nodes.items[idx];
        const a = n.op.while_loop;
        const ins = n.inputs.slice();
        const S = a.n_state;
        const C = a.n_caps;
        try pad(w, indent);
        try w.print("const {s} = blk{d}: {{\n", .{ names[idx], idx });
        try pad(w, indent + 4);
        try w.print("const W{d} = struct {{\n", .{idx});
        try pad(w, indent + 8);
        try w.print("caps: [{d}]zml.Tensor,\n", .{C});
        try pad(w, indent + 8);
        try w.print("pub const State = struct {{ i: zml.Tensor, s: [{d}]zml.Tensor }};\n", .{S});
        try pad(w, indent + 8);
        try w.print("pub fn cond(_: @This(), st{d}: @This().State) zml.Tensor {{\n", .{idx});
        try pad(w, indent + 12);
        try w.print("return st{d}.i.cmp(.LT, zml.Tensor.scalar({d}, .i32));\n", .{ idx, a.trip });
        try pad(w, indent + 8);
        try w.writeAll("}\n");
        try pad(w, indent + 8);
        try w.print("pub fn body(w{d}: @This(), st{d}: @This().State) @This().State {{\n", .{ idx, idx });
        try pad(w, indent + 12);
        try w.print("_ = &w{d};\n", .{idx});
        try emitParams(prog, a.start, a.end, w, names, indent + 12, S, C, true, idx);
        try @import("../emit.zig").emitScope(prog, w, names, a.start, a.end, a.start + 1, indent + 12);
        try pad(w, indent + 12);
        try w.print("return .{{ .i = st{d}.i.addConstant(1), .s = .{{ ", .{idx});
        for (a.results.slice(), 0..) |r, j| try w.print("{s}{s}", .{ if (j > 0) ", " else "", names[r] });
        try w.writeAll(" } };\n");
        try pad(w, indent + 8);
        try w.writeAll("}\n");
        try pad(w, indent + 4);
        try w.writeAll("};\n");
        try pad(w, indent + 4);
        try w.print("break :blk{d} zml.ops.@\"while\"(W{d}, .{{ .caps = .{{ ", .{ idx, idx });
        for (ins[S..], 0..) |in, j| try w.print("{s}{s}", .{ if (j > 0) ", " else "", names[in] });
        try w.writeAll(" } }, .{ .i = zml.Tensor.scalar(0, .i32), .s = .{ ");
        for (ins[0..S], 0..) |in, j| try w.print("{s}{s}", .{ if (j > 0) ", " else "", names[in] });
        try w.print(" }} }}).s[{d}];\n", .{a.pick});
        try pad(w, indent);
        try w.writeAll("};\n");
    }

    pub fn emit(_: Attrs, _: *const Node, _: *Writer, _: []const []const u8) Writer.Error!void {
        unreachable;
    }

    /// Region ends map through the node right after the region, which stays live: the
    /// control op itself.
    pub fn remap(a: *Attrs, map: []const u32) void {
        a.end = map[a.end];
        a.start = map[a.start];
        for (a.results.mut()) |*r| r.* = map[r.*];
    }

    pub fn regions(a: Attrs) [2][2]u32 {
        return .{ .{ a.start, a.end }, .{ 0, 0 } };
    }

    pub fn roots(a: Attrs) [4]u32 {
        var res: [4]u32 = @splat(a.results.slice()[0]);
        @memcpy(res[0..a.results.len], a.results.slice());
        return res;
    }
};

fn pad(w: *Writer, n: usize) Writer.Error!void {
    for (0..n) |_| try w.writeByte(' ');
}

/// Declares the param nodes of a region from the loop state, captures and counter.
fn emitParams(prog: *const ir.Program, start: u32, end: u32, w: *Writer, names: []const []const u8, indent: usize, S: usize, C: usize, loop: bool, owner: u32) Writer.Error!void {
    for (start..end) |i| {
        const n = prog.nodes.items[i];
        if (n.scope != start + 1 or n.op != .param) continue;
        const j = n.op.param.index;
        try pad(w, indent);
        if (loop and j < S) {
            try w.print("const {s} = st{d}.s[{d}];\n", .{ names[i], owner, j });
        } else if (j < S + C) {
            try w.print("const {s} = w{d}.caps[{d}];\n", .{ names[i], owner, j - (if (loop) S else 0) });
        } else {
            try w.print("const {s} = st{d}.i;\n", .{ names[i], owner });
        }
        try pad(w, indent);
        try w.print("_ = &{s};\n", .{names[i]});
    }
}

// -----------------------------------------------------------------------------

pub const cond = struct {
    pub const Kind = enum { if_, if2 };
    pub const Attrs = struct {
        kind: Kind,
        t_start: u32,
        t_end: u32,
        f_start: u32,
        f_end: u32,
        n_caps: u8,
        t_results: List(u32, 2),
        f_results: List(u32, 2),
        pick: u8,
    };
    pub const weight = 3;

    pub fn propose(g: *Gen) k.GenError!?k.Proposal {
        if (g.depth >= max_depth) return error.Reject;
        const kind = g.rng.enumValue(Kind);
        // A single element bool predicate, rank 0 or 1x1.
        var pred = g.pick(.{ .dtype = .bool, .max_rank = 2, .min_count = 1 }) orelse
            try g.freshInput(if (g.chance(0.7)) Shape.init(.{}, .bool) else Shape.init(.{1}, .bool));
        if (g.shapeOf(pred).count() != 1) pred = try g.freshInput(Shape.init(.{}, .bool));
        const n_caps = g.intIn(u8, 1, 3);
        var ids: [4]u32 = undefined;
        ids[0] = pred;
        for (0..n_caps) |i| ids[1 + i] = try g.operand(.{ .max_rank = 3 });
        const start: u32 = @intCast(g.prog.nodes.items.len);
        errdefer g.rollback(start);
        var bindings: [3]Value = undefined;
        for (0..n_caps) |i| bindings[i] = g.valueOf(ids[1 + i]);
        const saved = .{ g.scope, g.bindings, g.depth };
        defer {
            g.scope = saved[0];
            g.bindings = saved[1];
            g.depth = saved[2];
        }
        g.depth += 1;
        var a: Attrs = .{ .kind = kind, .t_start = start, .t_end = 0, .f_start = 0, .f_end = 0, .n_caps = n_caps, .t_results = .{}, .f_results = .{}, .pick = 0 };
        const t_scope = try openRegion(g, bindings[0..n_caps]);
        try genBody(g, g.intIn(usize, 1, 5));
        a.t_end = @intCast(g.prog.nodes.items.len);
        // Results come from the true branch; the false branch must produce the same shapes.
        const n_res = g.intIn(usize, 1, 2);
        for (0..n_res) |_| {
            // Prefer results with the shape of a capture: the false branch can always
            // return its param then.
            var cand: ?u32 = null;
            if (g.chance(0.7)) {
                const b = bindings[g.rng.uintLessThan(usize, n_caps)];
                cand = regionResult(g, start, t_scope, b.shape);
            }
            if (cand == null) {
                const c = g.rng.uintLessThan(u32, a.t_end - start) + start;
                if (g.prog.nodes.items[c].scope == t_scope and !g.values.items[c].allow_inf) cand = c;
            }
            a.t_results.append(cand orelse return error.Reject);
        }
        g.scope = saved[0];
        g.bindings = saved[1];
        a.f_start = a.t_end;
        const f_scope = try openRegion(g, bindings[0..n_caps]);
        try genBody(g, g.intIn(usize, 1, 5));
        a.f_end = @intCast(g.prog.nodes.items.len);
        for (a.t_results.slice()) |r| a.f_results.append(regionResult(g, a.f_start, f_scope, g.shapeOf(r)) orelse return error.Reject);
        g.scope = saved[0];
        g.bindings = saved[1];
        a.pick = g.intIn(u8, 0, @intCast(n_res - 1));
        _ = try g.commit(.{ .op = .{ .cond = a }, .inputs = try k.dupeIds(g, ids[0 .. 1 + n_caps]), .shape = g.shapeOf(a.t_results.slice()[a.pick]) });
        return null;
    }

    pub fn eval(e: *Eval, a: Attrs, node: *const Node, ins: []const Value) Eval.Error!Value {
        const p = ins[0].getI(0) != 0;
        const caps = ins[1..];
        // if2 evaluates both branches.
        var t: ?[]Value = null;
        var f: ?[]Value = null;
        if (p or a.kind == .if2) t = try evalRegion(e, a.t_start, a.t_end, a.t_start + 1, caps);
        if (!p or a.kind == .if2) f = try evalRegion(e, a.f_start, a.f_end, a.f_start + 1, caps);
        var v = if (p)
            try t.?[a.t_results.slice()[a.pick] - a.t_start].dupe(e.allocator)
        else
            try f.?[a.f_results.slice()[a.pick] - a.f_start].dupe(e.allocator);
        v.shape = node.shape;
        return v;
    }

    pub fn lowerCtl(ctx: *lower_mod.Ctx, tensors: []Tensor, idx: u32, ins: []const Tensor) Tensor {
        _ = tensors;
        const a = ctx.prog.nodes.items[idx].op.cond;
        inline for (1..4) |C| inline for (1..3) |R| {
            if (a.n_caps == C and a.t_results.len == R) return lowerSized(C, R, idx, a, ins);
        };
        unreachable;
    }

    fn branch(comptime C: usize, comptime R: usize, ctx: *lower_mod.Ctx, start: u32, end: u32, results: []const u32, caps: [C]Tensor) [R]Tensor {
        var b = caps;
        lower_mod.lowerRegion(ctx, start, end, start + 1, &b);
        var res: [R]Tensor = undefined;
        for (0..R) |j| res[j] = ctx.tensors[results[j]];
        return res;
    }

    fn lowerSized(comptime C: usize, comptime R: usize, idx: u32, a: Attrs, ins: []const Tensor) Tensor {
        var caps: [C]Tensor = undefined;
        for (0..C) |j| caps[j] = ins[1 + j];
        if (a.kind == .if2) {
            const ctx = lower_mod.current_ctx.?;
            const t = branch(C, R, ctx, a.t_start, a.t_end, a.t_results.slice(), caps);
            const f = branch(C, R, ctx, a.f_start, a.f_end, a.f_results.slice(), caps);
            return zml.ops.if2(ins[0], t, f)[a.pick];
        }
        const If = struct {
            caps: [C]Tensor,
            node: u32,
            pub fn onTrue(c: @This()) [R]Tensor {
                const ctx = lower_mod.current_ctx.?;
                const at = ctx.prog.nodes.items[c.node].op.cond;
                return branch(C, R, ctx, at.t_start, at.t_end, at.t_results.slice(), c.caps);
            }
            pub fn onFalse(c: @This()) [R]Tensor {
                const ctx = lower_mod.current_ctx.?;
                const at = ctx.prog.nodes.items[c.node].op.cond;
                return branch(C, R, ctx, at.f_start, at.f_end, at.f_results.slice(), c.caps);
            }
        };
        return zml.ops.@"if"(If, .{ .caps = caps, .node = idx }, ins[0])[a.pick];
    }

    pub fn lower(_: Attrs, _: *const Node, _: []const Tensor) Tensor {
        unreachable;
    }

    pub fn emitCtl(prog: *const ir.Program, idx: u32, w: *Writer, names: []const []const u8, indent: usize) Writer.Error!void {
        const n = prog.nodes.items[idx];
        const a = n.op.cond;
        const ins = n.inputs.slice();
        const C = a.n_caps;
        const R = a.t_results.len;
        const emit_mod = @import("../emit.zig");
        try pad(w, indent);
        try w.print("const {s} = blk{d}: {{\n", .{ names[idx], idx });
        try pad(w, indent + 4);
        try w.print("const If{d} = struct {{\n", .{idx});
        try pad(w, indent + 8);
        try w.print("caps: [{d}]zml.Tensor,\n", .{C});
        for ([_]bool{ true, false }) |on_true| {
            const start = if (on_true) a.t_start else a.f_start;
            const end = if (on_true) a.t_end else a.f_end;
            const results = if (on_true) a.t_results.slice() else a.f_results.slice();
            try pad(w, indent + 8);
            try w.print("pub fn {s}(w{d}: @This()) [{d}]zml.Tensor {{\n", .{ if (on_true) "onTrue" else "onFalse", idx, R });
            try emitParams(prog, start, end, w, names, indent + 12, 0, C, false, idx);
            try emit_mod.emitScope(prog, w, names, start, end, start + 1, indent + 12);
            try pad(w, indent + 12);
            try w.writeAll("return .{ ");
            for (results, 0..) |r, j| try w.print("{s}{s}", .{ if (j > 0) ", " else "", names[r] });
            try w.writeAll(" };\n");
            try pad(w, indent + 8);
            try w.writeAll("}\n");
        }
        try pad(w, indent + 4);
        try w.writeAll("};\n");
        try pad(w, indent + 4);
        try w.print("const caps{d}: If{d} = .{{ .caps = .{{ ", .{ idx, idx });
        for (ins[1..], 0..) |in, j| try w.print("{s}{s}", .{ if (j > 0) ", " else "", names[in] });
        try w.writeAll(" } };\n");
        try pad(w, indent + 4);
        if (a.kind == .if2) {
            try w.print("break :blk{d} zml.ops.if2({s}, caps{d}.onTrue(), caps{d}.onFalse())[{d}];\n", .{ idx, names[ins[0]], idx, idx, a.pick });
        } else {
            try w.print("break :blk{d} zml.ops.@\"if\"(If{d}, caps{d}, {s})[{d}];\n", .{ idx, idx, idx, names[ins[0]], a.pick });
        }
        try pad(w, indent);
        try w.writeAll("};\n");
    }

    pub fn emit(_: Attrs, _: *const Node, _: *Writer, _: []const []const u8) Writer.Error!void {
        unreachable;
    }

    /// The true region ends where the false one starts, the false one at the op itself.
    pub fn remap(a: *Attrs, map: []const u32) void {
        a.t_end = map[a.t_end];
        a.t_start = map[a.t_start];
        a.f_end = map[a.f_end];
        a.f_start = map[a.f_start];
        for (a.t_results.mut()) |*r| r.* = map[r.*];
        for (a.f_results.mut()) |*r| r.* = map[r.*];
    }

    pub fn regions(a: Attrs) [2][2]u32 {
        return .{ .{ a.t_start, a.t_end }, .{ a.f_start, a.f_end } };
    }

    pub fn roots(a: Attrs) [4]u32 {
        var res: [4]u32 = undefined;
        @memcpy(res[0..a.t_results.len], a.t_results.slice());
        @memcpy(res[a.t_results.len..][0..a.f_results.len], a.f_results.slice());
        // Pad with a result so the fixed size array only holds live roots.
        for (a.t_results.len + a.f_results.len..4) |j| res[j] = a.t_results.slice()[0];
        return res;
    }
};
